window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"vQspFC5KjMk","speaker":"Irakli Kobakhidze","role":"Prime Minister","country":"Georgia","region":"Asia-Pacific","url":"https://www.youtube.com/watch?v=vQspFC5KjMk","date":"20260925","title":"🇬🇪 Georgia - Prime Minister Addresses United Nations General Debate, 81st Session | #UNGA","seconds":519,"words":1171,"counts":{"claims":13,"promises":2,"attacks":0},"topics":[{"topic":"Georgia economy","share":0.3786,"seconds":197},{"topic":"UN reforms","share":0.3692,"seconds":192},{"topic":"Georgia connectivity","share":0.1334,"seconds":69},{"topic":"Georgia occupation","share":0.1189,"seconds":62}],"timeline":[[1,67,"UN reforms"],[68,135,"UN reforms"],[136,198,"Georgia occupation"],[199,268,"Georgia connectivity"],[269,342,"Georgia economy"],[344,407,"Georgia economy"],[408,468,"Georgia economy"],[470,529,"UN reforms"]],"stances":{"UN reforms":"Irakli Kobakhidze states that maintaining peace and strengthening international cooperation are key priorities amidst global changes.","Georgia occupation":"Irakli Kobakhidze states that 20% of Georgia is under Russian occupation and calls for peace and economic growth to extend to all citizens regardless of artificial boundaries.","Georgia connectivity":"Irakli Kobakhidze states that Georgia is well-positioned to strengthen regional connectivity and plans significant infrastructure investments to support this agenda.","Georgia economy":"Irakli Kobakhidze states that Georgia has achieved strong economic growth and aims to enhance digital connectivity between Europe and Asia through strategic infrastructure projects."},"claims":[{"t":40,"quote":"a nation shaped by centuries of history, resilience, and engagement with a changing world","topic":"UN reforms","kind":"fact"},{"t":93,"quote":"Few countries understand the value of peace, stability, and sovereignty as deeply as Georgia does.","topic":"UN reforms","kind":"self_credit"},{"t":100,"quote":"For centuries, we stood at the crossroads of civilizations, open to diverse cultures, peoples, and ideas, while steadfastly preserving our own distinct identity and character.","topic":"UN reforms","kind":"fact"},{"t":141,"quote":"20% of our country remains under the occupation of the Russian Federation, while hundreds of our citizens continue to live in displacement, unable to return to their homes.","topic":"Georgia occupation","kind":"number"},{"t":244,"quote":"Our network of free trade agreements provides access to a market of approximately 2.3 billion consumers.","topic":"Georgia connectivity","kind":"number"},{"t":293,"quote":"Over the past 5 years, our economy has grown by an average of 9.3% annually, and this momentum has continued in 2026 with growth reaching 7.9% in the first 7 months of the year.","topic":"Georgia economy","kind":"number"},{"t":307,"quote":"As the International Monetary Fund projects, Georgia will deliver one of the fastest growth rates in the medium term among regional and European countries, averaging 5.4%.","topic":"Georgia economy","kind":"fact"},{"t":328,"quote":"Despite the global uncertainty, Georgia's FDI to GDP ratio is one of the highest among peer countries and averaged over 6% of GDP in highlighting the confidence of investors in the country's growth potential.","topic":"Georgia economy","kind":"number"},{"t":376,"quote":"including a triple decline in Georgia's poverty rate, which dropped from 21.3% to 7.1% since 2020","topic":"Georgia economy","kind":"number"},{"t":408,"quote":"These priorities are fully aligned with Georgia's commitment to the Sustainable Development Goals, and are reflected in our new United Nations Sustainable Development Cooperation Framework for","topic":"Georgia economy","kind":"fact"},{"t":424,"quote":"our ambition for the coming decade is to transform Georgia from an upper middle-income country into a high-income economy, underpinned by greater economic diversification, a growing share of knowledge-based activities, and broad-based prosperity.","topic":"Georgia economy","kind":"self_credit"},{"t":473,"quote":"the United Nations remains indispensable as a forum for dialogue and collective action","topic":"UN reforms","kind":"fact"},{"t":492,"quote":"Georgia stands ready to work constructively with international partners and contribute actively to this process","topic":"UN reforms","kind":"self_credit"}],"promises":[{"t":254,"quote":"Georgia plans to invest USD 7 billion by 2032 in major transport infrastructure, modernizing the railway, developing the Anaklia deep sea port, building a new international airport in Tbilisi, and expanding the highway network.","topic":"Georgia connectivity","kind":"promise"},{"t":392,"quote":"Over the next 5 years, our focus will therefore be on narrowing disparities between urban and rural communities, expanding opportunities across every region, and ensuring that the benefits of economic growth are shared widely, and that no one is left behind.","topic":"Georgia economy","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":1,"topic":"UN reforms","text":"The assembly will now hear an address by his Excellency Irakli Kobakhidze, Prime Minister of Georgia. I request protocol to escort his Excellency and invite him to address the &gt;&gt; Mr. President, &gt;&gt; Mr. Secretary-General, Excellencies, distinguished delegates, dear friends of Georgia, it's a privilege to stand before this on behalf of Georgia, a nation shaped by centuries of history, resilience, and engagement with a changing world. We meet at a time of considerable change in the international environment. Developments in different parts of the world are challenging existing arrangements and raising questions about the future of the international order. In this context, maintaining peace and strengthening international cooperation remain key priorities."},{"t":68,"topic":"UN reforms","text":"In light of the growing number of global challenges, coordinated responses to common obstacles, conflict prevention, and the achievement of the 2030 agenda for sustainable development are possible only through strengthened international cooperation and the shared commitment to collective action. Lasting peace cannot be imposed by force. It must be built through communication and mutual respect. Few countries understand the value of peace, stability, and sovereignty as deeply as Georgia does. For centuries, we stood at the crossroads of civilizations, open to diverse cultures, peoples, and ideas, while steadfastly preserving our own distinct identity and character. Georgia's statehood has been tested more than once, but these challenges have only strengthened our determination to choose our own path. The trials of history have also taught us that sovereignty can never be taken for granted, that stability must be protected, and the strength of the international order ultimately depends on the same principles being upheld for every nation."},{"t":136,"topic":"Georgia occupation","text":"Our commitment to these principles carries particular meaning for Georgia. 20% of our country remains under the occupation of the Russian Federation, while hundreds of our citizens continue to live in displacement, unable to return to their homes. While restoring trust is a major theme of this year's session, I would like to address our Abkhaz and Ossetian brothers and sisters. We have shared a homeland and a history for centuries. The divisions of today cannot erase that history, nor should they determine the future of our children. We believe that the dividends of peace and economic growth of Georgia should know no artificial boundaries. It must reach the people living in our occupied historic regions as well, who remain and will always remain part of our shared future. The challenges facing our country also remind us that national stability and success cannot be separated from the wider regional context. We believe that the South Caucasus should not be defined by the divisions of the past."},{"t":199,"topic":"Georgia connectivity","text":"We have consistently sought to act as an honest broker in regional initiatives, fostering cooperation and contributing to peaceful solutions. Today, we see a genuine opportunity to turn a new page and build a more peaceful and interconnected region based on shared commitment to a better future. This spirit of cooperation must also translate into tangible economic opportunities for the region. As an integral part of the South Caucasus and the middle corridor, Georgia is well positioned to strengthen connectivity between Central Asia and Europe. Our strategic location and direct access to the Black Sea facilitate trade and investment, linking landlocked countries in our wider region to global supply Our network of free trade agreements provides access to a market of approximately 2.3 billion consumers. To support and further advance connectivity agenda, Georgia plans to invest USD 7 billion by 2032 in major transport infrastructure, modernizing the railway, developing the Anaklia deep sea port, building a new international airport in Tbilisi, and expanding the highway network."},{"t":269,"topic":"Georgia economy","text":"At the same time, we believe that physical and digital connectivity are two parts of the same strategic Through a Black Sea submarine fiber optic connection and next-generation data infrastructure, Georgia aims to strengthen secure, resilient, and diversified digital links between Europe and Asia. These ambitions are underpinned by Georgia's strong economic performance. Over the past 5 years, our economy has grown by an average of 9.3% annually, and this momentum has continued in 2026 with growth reaching 7.9% in the first 7 months of the year. As the International Monetary Fund projects, Georgia will deliver one of the fastest growth rates in the medium term among regional and European countries, averaging 5.4%. As one of the fastest-growing economies worldwide, we are actively building an innovation-oriented business-friendly environment that supports both local and enterprises. Despite the global uncertainty, Georgia's FDI to GDP ratio is one of the highest among peer countries and averaged over 6% of GDP in highlighting the confidence of investors in the country's growth potential."},{"t":344,"topic":"Georgia economy","text":"Georgia's FDI outlook is supported by a pipeline of large, multi-year investment projects across transport and logistics, energy infrastructure, tourism, and real Yet, the true measure of success is how it improves people's lives. Strong economic performance must translate into tangible social outcomes, higher output per person, rising real wages, declining poverty, better employment opportunities, and greater economic resilience. We're already seeing these outcomes reflected in measurable improvements, including a triple decline in Georgia's poverty rate, which dropped from 21.3% to 7.1% since 2020. Yet, this achievement is only part of the broader transformation we seek to Over the next 5 years, our focus will therefore be on narrowing disparities between urban and rural communities, expanding opportunities across every region, and ensuring that the benefits of economic growth are shared widely, and that no one is left behind."},{"t":408,"topic":"Georgia economy","text":"These priorities are fully aligned with Georgia's commitment to the Sustainable Development Goals, and are reflected in our new United Nations Sustainable Development Cooperation Framework for Looking further ahead, our ambition for the coming decade is to transform Georgia from an upper middle-income country into a high-income economy, underpinned by greater economic diversification, a growing share of knowledge-based activities, and broad-based prosperity. Excellencies, ladies and gentlemen, the progress we seek at home is inseparable from the cooperation we build beyond our borders. Georgia remains open to meaningful engagement with every international partner prepared to engage with us on the basis of mutual respect and sovereign equality. We believe that lasting partnerships are built through dialogue and never through pressure or coercion. The principles of respect and cooperation are also at the heart of effective multilateralism."},{"t":470,"topic":"UN reforms","text":"At the time of growing global uncertainty, the United Nations remains indispensable as a forum for dialogue and collective action. In this regard, the UN 80 initiative provides a valuable opportunity to strengthen the effectiveness and capacity of the United Nations while further enhancing its transparency and Georgia stands ready to work constructively with international partners and contribute actively to this process. We firmly support reforms that will strengthen the organization's capacity to deliver better and become more results-oriented. The choice we make today will shape the world we leave to future generations. Let's ensure that we leave them a world that is more peaceful, secure, and united than the one we know today. Thank you very much. &gt;&gt; On behalf of the assembly, I wish to thank the Prime Minister of Georgia."}],"compare":[{"topic":"UN & its reform","share":0.3692,"mean":0.2039,"rank":26,"others":170},{"topic":"Georgia","share":0.1189,"mean":0.0,"rank":1,"others":0}]};
